def _mechanism(row: tuple[str, ...]) -> dict[str, Any]:
    identity, family, name, problem, effect, mechanism, applicable, contraindicated, planning, prose, signal, failure, repair = row
    return {
        "schema_version": "narrative-craft-mechanism.v1", "mechanism_id": identity, "version": 1,
        "family": family, "name": name, "narrative_problem": problem,
        "desired_reader_effect": effect, "abstract_mechanism": mechanism,
        "prerequisites": [applicable, "已有批准的场景目标、POV和事件边界"],
        "applicability_conditions": [applicable, f"当前叙事问题涉及：{problem}"],
        "contraindications": [contraindicated, "为使用技法必须改变未获批准的事件、人物知识或世界规则"],
        "affinity": {"genre": ["wuxia", "xuanhuan", "chinese_serial"], "scene_type": _SCENES[family], "pov": ["limited", "first_person"], "pacing": ["variable"]},
        "planning_guidance": planning,
        "scene_realization_guidance": f"在当前场景选择一个明确使用位置；{planning}。实现目标：{effect}。",
        "prose_realization_guidance": prose,
        "composition": {"compatible": [], "complementary": _COMPLEMENTS.get(identity, []), "conflicting": [], "requires": [], "precedes": (["satisfaction-settlement"] if identity == "setup-progress-payoff" else [])},
        "success_signals": [signal], "failure_modes": [failure, "为了显露技巧而压过人物声音、场景目标或必要信息"],
        "review_checks": [f"定位正文证据检查：{signal}。证据不足标记UNCERTAIN。", f"定位并检查副作用：{failure}。不得仅凭技巧名称判定成功。"],
        "repair_strategies": [repair, "只修复相关句段，保留已成功的其他机制和已批准事件结果"],
        "preservation_constraints": ["不得改变已接受Canon、世界规则或批准的场景结果", "保留POV知识边界、人物声音与空间时间因果", "保留其他已满足的Craft效果及未到兑现时点的伏笔义务"],
        "provenance": {"origin": "REPOSITORY_ORIGINAL", "attribution": "Novel Forge original abstract mechanism catalog; no reference-work prose or entity templates", "abstraction_policy_version": "repository-original-craft-v1", "source_observation_asset_version_ids": [], "confidence": "HYPOTHESIS", "supersedes_card_asset_version_id": ""},
        "validation_evidence": [], "effect_evidence": [],
    }


CORE_CRAFT_MECHANISMS = tuple(_mechanism(row) for row in _ROWS)
